import './cloud-sync.js';
import{MODELING_TRACKS,MODELING_CHAIN,MODELING_DIAGNOSTIC,recommendModelingTrack,choiceIndex,freshChoiceIndex,createBlankModelingLearner}from'./modeling-data.js?v=modeling3';

const $=s=>document.querySelector(s),storageKey='mathlab-modeling-v1',memory={};
function blankStore(){return{a:createBlankModelingLearner(),b:createBlankModelingLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankModelingLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankModelingLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function saveLearnerChoice(){store={...readStore(),learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return MODELING_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[MODELING_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=MODELING_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.transfer=state.evidence.transfer==='unknown'?'learning':state.evidence.transfer}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,420)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function arrange(correct,others,seed){const values=[...new Set(others.filter(v=>v!==correct))],index=typeof seed==='number'?((seed%(values.length+1))+(values.length+1))%(values.length+1):choiceIndex(seed,values.length+1);values.splice(index,0,correct);return values}
function textChoices(correct,others,attr,seed=`${track().id}:${attr}`){return `<div class="answer-grid">${arrange(correct,others,seed).map(v=>`<button class="choice" data-${attr}="${v===correct?'correct':'wrong'}">${esc(v)}</button>`).join('')}</div>`}
function numberChoices(correct,others,attr,seed=`${track().id}:${attr}:${Number(work.index)||0}`){return `<div class="answer-grid number-choices">${arrange(correct,others,seed).map(v=>`<button class="choice" data-${attr}="${v}">${v}</button>`).join('')}</div>`}
function storyCard(text,label='THE SITUATION'){const parts=text.split(/(?<=[.!?])\s+/);return `<div class="story-card"><small>${label}</small>${parts.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`}
function planFlow(steps,current=0){return `<div class="plan-flow">${steps.map((s,i)=>`<div class="plan-step ${i<current?'done':i===current?'current':''}"><span>${i+1}</span><strong>${i<current?work.answers?.[i]??'✓':i===current?'?':'…'}</strong><small>${esc(s.prompt)}</small></div>`).join('<b>→</b>')}</div>`}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=MODELING_DIAGNOSTIC.length){state.track=state.track||recommendModelingTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful problem-solving challenges. It is not a grade label.</p><button class="primary" data-action="start">Separate what matters →</button></div>`;return}const q=MODELING_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/MODELING_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${MODELING_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Explain what each number or fact means.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That matches the situation.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},450)})}
function renderSort(){const p=track().sort;if(!work.info){$('#activity').innerHTML=`<p class="eyebrow">QUESTION → USEFUL FACTS → MODEL</p><h3>Which information changes the answer?</h3>${storyCard(p.story)}${textChoices(p.answer,['Use every number and every detail.','Use only the number nearest the question.'],'info-answer')}${controls()}${hint('Say what the question asks. Keep facts that change that quantity; set descriptions and timing aside unless they affect it.')}`;document.querySelectorAll('[data-info-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.infoAnswer==='correct'){work={...work,info:true};saveSession();feedback('You kept the quantities that control the answer. Now explain why the extra fact can be ignored.','good');setTimeout(renderMission,350)}else miss('Do not use a fact just because it contains a number. Ask whether changing it would change the answer.')})}else{$('#activity').innerHTML=`<p class="eyebrow">PROVE THE INFORMATION CHOICE</p><h3>Why is this the useful information?</h3>${storyCard(p.story)}${textChoices(p.proof,p.decoys,'info-proof')}${controls()}${hint('A strong explanation names both the useful quantities and the fact that does not affect the requested amount.')}`;document.querySelectorAll('[data-info-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.infoProof==='correct'){feedback('Yes. Relevance comes from the question, not from using every number.','good');complete(1,['information'])}else miss('Check whether the explanation connects each chosen fact to the question.')})}}
function renderPlan(){const p=track().plan,index=Number(work.index)||0,answers=work.answers||[];if(index<p.steps.length){const step=p.steps[index];$('#activity').innerHTML=`<p class="eyebrow">ONE PLAN · ONE MEANINGFUL STEP AT A TIME</p><h3>${esc(step.prompt)}</h3>${storyCard(p.story)}${planFlow(p.steps,index)}${numberChoices(step.answer,step.decoys,'plan-answer')}${controls()}${hint(index===0?'Start with the quantities that create the whole or total.':'Use the previous result. Ask what changes next in the story.')}`;document.querySelectorAll('[data-plan-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.planAnswer)===step.answer){work={...work,index:index+1,answers:[...answers,step.answer]};saveSession();feedback('That intermediate result matches the story.','good');setTimeout(renderMission,350)}else miss('Name what this step should measure. Then choose the operation that creates that quantity.')});return}$('#activity').innerHTML=`<p class="eyebrow">PROVE THE COMPLETE PLAN</p><h3>${esc(p.equation)}</h3>${storyCard(p.story)}${planFlow(p.steps,p.steps.length)}${textChoices(p.proof,p.decoys,'plan-proof')}${controls()}${hint('The proof must explain the meaning of every operation and carry each intermediate result into the next step.')}`;document.querySelectorAll('[data-plan-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.planProof==='correct'){feedback('Yes. Every operation now has a job in the story.','good');complete(2,['plan'])}else miss('Reject a plan that merely uses every number without matching the situation.')})}
function renderCheck(){const p=track().check;$('#activity').innerHTML=`<p class="eyebrow">ERROR DETECTIVE</p><h3>What is wrong, and how should the model change?</h3>${storyCard(p.story,'A LEARNER’S MODEL')}<div class="reasonableness-card"><strong>Check three things</strong><span>What does each number mean?</span><span>Does the operation match the action?</span><span>Is the result reasonable?</span></div>${textChoices(p.answer,p.decoys,'check-answer')}${controls()}${hint('Do not only say “wrong.” Point to the operation that does not match the story, then state the corrected order.')}`;document.querySelectorAll('[data-check-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.checkAnswer==='correct'){feedback('Exactly. You diagnosed the meaning error and repaired the plan.','good');complete(3,['revision'],true)}else miss('A complete diagnosis names the mismatch and gives a corrected plan.')})}
function freshSteps(p,index){return p.steps.map((answer,i)=>({prompt:i===0?'Find the first total.':i===p.steps.length-1?'Find the final answer.':'Use that result for the next change.',answer,decoys:[answer+p.steps[0],Math.abs(answer-(p.steps[i-1]||1))]}))}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000)),name=learner==='a'?'Ella':'Mila';$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the plan has faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether ${name} can build a new model without copying today’s steps.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses a changed story. It will not count as delayed evidence or earn credits.</p></div>`;return}const p=ready?track().fresh.challenge:track().fresh.preview,steps=freshSteps(p),index=Number(work.index)||0,answers=work.answers||[];if(!work.model){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · BUILD A NEW MODEL':'FAMILY PREVIEW · MODEL FIRST'}</p><h3>Which complete model matches the story?</h3>${storyCard(p.story)}${textChoices(p.model,p.modelDecoys,'fresh-model',freshChoiceIndex(track().id,'model',0,ready,3))}${controls()}${hint('Build the whole amount first. Then follow each change in story order. Use parentheses when a result must be found before division.')}`;document.querySelectorAll('[data-fresh-model]').forEach(b=>b.onclick=()=>{if(b.dataset.freshModel==='correct'){work={...work,model:true};saveSession();feedback('That model matches the quantities and their order. Now calculate each step.','good');setTimeout(renderMission,350)}else miss('Explain what each operation would do in the story. Reject a model that changes the order or meaning.')});return}if(index<steps.length){const step=steps[index];$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW SITUATION':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>${esc(step.prompt)}</h3>${storyCard(p.story)}${planFlow(steps,index)}${numberChoices(step.answer,step.decoys,'fresh-answer',freshChoiceIndex(track().id,'answer',index,ready,3))}${controls()}${hint('State what this step measures. Use the result from the previous step instead of returning to the original numbers.')}`;document.querySelectorAll('[data-fresh-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.freshAnswer)===step.answer){work={...work,index:index+1,answers:[...answers,step.answer]};saveSession();feedback('That step preserves the meaning of the plan.','good');setTimeout(renderMission,350)}else miss('Check what quantity should exist after this step and whether the answer is reasonable.')});return}$('#activity').innerHTML=`<p class="eyebrow">ONE PROOF FOR THE COMPLETE MODEL</p><h3>Final answer: ${p.steps.at(-1)}</h3>${storyCard(p.story)}${textChoices(p.proof,p.decoys,'fresh-proof',freshChoiceIndex(track().id,'proof',0,ready,3))}${controls()}${hint('The proof must show each exact intermediate result, the correct operation, and the final unit.')}`;document.querySelectorAll('[data-fresh-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.freshProof==='correct'){feedback(ready?'You transferred the full modeling process to a fresh problem after a delay.':'Preview complete. Return later for fresh evidence.','good');complete(4,['plan','transfer'],false,!ready)}else miss('Reject any proof that changes the order or cannot explain what each result means.')})}
function renderComplete(i){const m=MODELING_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=MODELING_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderSort();else if(i===2)renderPlan();else if(i===3)renderCheck();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=MODELING_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(MODELING_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankModelingLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const name=learner==='a'?'Ella':'Mila',labels={information:'Choose useful information',plan:'Build an ordered plan',revision:'Find & fix a model',transfer:'Fresh transfer'};$('#evidenceTitle').textContent=`${name}’s learning evidence`;$('#reviewBannerTitle').textContent=`Built for ${name} · waiting family review`;$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['modeling-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankModelingLearner();sessionMissionId=null;ensureState();saveLearnerChoice();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the word-problem review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankModelingLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
